module TopModule (
  input clk,
  input in,
  input reset,
  output done
);

  reg [2:0] shift_reg;
  reg done_reg;

  always @(posedge clk) begin
    if (reset) begin
      shift_reg <= 3'b000;
      done_reg <= 1'b0;
    end else begin
      // Update shift register with new input
      shift_reg <= {shift_reg[1:0], in};

      // Check if all three bits are 1s or 0s
      if (shift_reg == 3'b111 || shift_reg == 3'b000) begin
        done_reg <= 1'b1;
      end else begin
        done_reg <= done_reg;
      end
    end
  end

  assign done = done_reg;

endmodule

